//! The metric tables of `promex.rs`, generated from HAProxy 3.5-dev8-885761-29 built with USE_PROMEX=1:
//! the families, their types and HELP texts are what that binary printed for a scrape, the `show stat` / `show info`
//! column of each from `stat_cols_px` / `stat_cols_info` (src/stats-proxy.c, src/stats.c).

pub struct Metric { pub name: &'static str, pub col: &'static str, pub counter: bool, pub help: &'static str }

